13	  getTranslatedDescription,
14	} = require('../lib/csp-evaluator.js');
15	
16	/** @typedef {import('../lib/csp-evaluator.js').Finding} Finding */
17	
18	const UIStrings = {
19	  /** Title of a Lighthouse audit that evaluates the security of a page's CSP. "CSP" stands for "Content Security Policy". "XSS" stands for "Cross Site Scripting". "CSP" and "XSS" do not need to be translated. */
20	  title: 'Ensure CSP is effective against XSS attacks',
21	  /** Description of a Lighthouse audit that evaluates the security of a page's CSP. This is displayed after a user expands the section to see more. No character length limits. 'Learn More' becomes link text to additional documentation. "CSP" stands for "Content Security Policy". "XSS" stands for "Cross Site Scripting". "CSP" and "XSS" do not need to be translated. */
22	  description: 'A strong Content Security Policy (CSP) significantly ' +
23	    'reduces the risk of cross-site scripting (XSS) attacks. ' +
24	    '[Learn more](https://web.dev/csp-xss/)',
25	  /** Summary text for the results of a Lighthouse audit that evaluates the security of a page's CSP. This is displayed if no CSP is being enforced. "CSP" stands for "Content Security Policy". "CSP" does not need to be translated. */
26	  noCsp: 'No CSP found in enforcement mode',
27	  /** Message shown when one or more CSPs are defined in a <meta> tag. Shown in a table with a list of other CSP bypasses and warnings. "CSP" stands for "Content Security Policy". "CSP" and "HTTP" do not need to be translated. */
28	  metaTagMessage: 'The page contains a CSP defined in a <meta> tag. ' +
29	    'Consider defining the CSP in an HTTP header if you can.',
30	  /** Label for a column in a data table; entries will be a directive of a CSP. "CSP" stands for "Content Security Policy". */
31	  columnDirective: 'Directive',
32	  /** Label for a column in a data table; entries will be the severity of an issue with the CSP. "CSP" stands for "Content Security Policy". */
33	  columnSeverity: 'Severity',
34	  /** Table item value calling out the presence of a syntax error. */
35	  itemSeveritySyntax: 'Syntax',
