40	class CspXss extends Audit {
41	  /**
42	   * @return {LH.Audit.Meta}
43	   */
44	  static get meta() {
45	    return {
46	      id: 'csp-xss',
47	      scoreDisplayMode: Audit.SCORING_MODES.INFORMATIVE,
48	      title: str_(UIStrings.title),
49	      description: str_(UIStrings.description),
