66	      })
67	      .flatMap(m => (m.content || '').split(','))
68	      .filter(rawCsp => rawCsp.replace(/\s/g, ''));
69	    const cspHeaders = mainResource.responseHeaders
70	      .filter(h => {
71	        return h.name.toLowerCase() === 'content-security-policy';
72	      })
73	      .flatMap(h => h.value.split(','))
74	      .filter(rawCsp => rawCsp.replace(/\s/g, ''));
75	
76	    return {cspHeaders, cspMetaTags};
77	  }
78	
79	  /**
80	   * @param {Finding} finding
81	   * @param {LH.IcuMessage=} severity
82	   * @return {LH.Audit.Details.TableItem}
83	   */
84	  static findingToTableItem(finding, severity) {
85	    return {
86	      directive: finding.directive,
87	      description: getTranslatedDescription(finding),
88	      severity,
89	    };
90	  }
91	
92	  /**
93	   * @param {Finding[][]} syntaxFindings
94	   * @param {string[]} rawCsps
95	   * @return {LH.Audit.Details.TableItem[]}
96	   */
97	  static constructSyntaxResults(syntaxFindings, rawCsps) {
98	    /** @type {LH.Audit.Details.TableItem[]} */
99	    const results = [];
100	
101	    for (let i = 0; i < syntaxFindings.length; ++i) {
102	      const items = syntaxFindings[i].map(f => this.findingToTableItem(f));
103	      if (!items.length) continue;
104	      results.push({
105	        severity: str_(UIStrings.itemSeveritySyntax),
106	        description: {
107	          type: 'code',
108	          value: rawCsps[i],
109	        },
110	        subItems: {
111	          type: 'subitems',
112	          items,
113	        },
114	      });
115	    }
116	
117	    return results;
118	  }
119	
120	  /**
121	   * @param {string[]} cspHeaders
122	   * @param {string[]} cspMetaTags
123	   * @return {{score: number, results: LH.Audit.Details.TableItem[]}}
124	   */
125	  static constructResults(cspHeaders, cspMetaTags) {
126	    const rawCsps = [...cspHeaders, ...cspMetaTags];
127	    if (!rawCsps.length) {
128	      return {
129	        score: 0,
130	        results: [{
131	          severity: str_(i18n.UIStrings.itemSeverityHigh),
132	          description: str_(UIStrings.noCsp),
133	          directive: undefined,
134	        }],
135	      };
136	    }
137	
138	    const {bypasses, warnings, syntax} = evaluateRawCspsForXss(rawCsps);
139	
140	    const results = [
141	      ...this.constructSyntaxResults(syntax, rawCsps),
142	      ...bypasses.map(f => this.findingToTableItem(f, str_(i18n.UIStrings.itemSeverityHigh))),
143	      ...warnings.map(f => this.findingToTableItem(f, str_(i18n.UIStrings.itemSeverityMedium))),
144	    ];
145	
146	    // Add extra warning for a CSP defined in a meta tag.
147	    if (cspMetaTags.length) {
