160	   * @param {LH.Audit.Context} context
161	   * @return {Promise<LH.Audit.Product>}
162	   */
163	  static async audit(artifacts, context) {
164	    const {cspHeaders, cspMetaTags} = await this.getRawCsps(artifacts, context);
165	    const {score, results} = this.constructResults(cspHeaders, cspMetaTags);
166	
167	    /** @type {LH.Audit.Details.Table['headings']} */
