172	      {key: 'severity', itemType: 'text', subItemsHeading: {key: 'severity'}, text: str_(UIStrings.columnSeverity)},
173	      /* eslint-enable max-len */
174	    ];
175	    const details = Audit.makeTableDetails(headings, results);
176	
177	    return {
178	      score,
